INSERT INTO `theory_topics` VALUES (1,'╨в╨╡╨╝╨░ 1. ╨Ю╨┐╨╡╤А╨░╤В╨╕╨▓╨╜╨░╤П ╨┐╨░╨╝╤П╤В╤М','<h3>╨Ю╨┐╨╡╤А╨░╤В╨╕╨▓╨╜╨░╤П ╨┐╨░╨╝╤П╤В╤М (╨Ю╨Ч╨г, RAM)</h3><p>╨Ю╨┐╨╡╤А╨░╤В╨╕╨▓╨╜╨░╤П ╨┐╨░╨╝╤П╤В╤М тАФ ╨╛╨┤╨╕╨╜ ╨╕╨╖ ╨▓╨░╨╢╨╜╨╡╨╣╤И╨╕╤Е ╨║╨╛╨╝╨┐╨╛╨╜╨╡╨╜╤В╨╛╨▓ ╤Б╨╕╤Б╤В╨╡╨╝╤Л, ╨╜╨╡╨╛╨▒╤Е╨╛╨┤╨╕╨╝╨░ ╨┤╨╗╤П ╤А╨░╨▒╨╛╤В╤Л ╨╛╨┐╨╡╤А╨░╤Ж╨╕╨╛╨╜╨╜╨╛╨╣ ╤Б╨╕╤Б╤В╨╡╨╝╤Л ╨╕ ╨┐╤А╨╕╨╗╨╛╨╢╨╡╨╜╨╕╨╣, ╨┤╨╗╤П ╨╛╨▒╤А╨░╨▒╨╛╤В╨║╨╕ ╨╕ ╨▓╤А╨╡╨╝╨╡╨╜╨╜╨╛╨│╨╛ ╤Е╤А╨░╨╜╨╡╨╜╨╕╤П ╨┤╨░╨╜╨╜╤Л╤Е. ╨Ю╨Ч╨г ╨╜╨╡ ╨┐╨╛╨╖╨▓╨╛╨╗╤П╨╡╤В ╤Е╤А╨░╨╜╨╕╤В╤М ╨╕╨╜╤Д╨╛╤А╨╝╨░╤Ж╨╕╤О ╨┐╨╛╤Б╨╗╨╡ ╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨╕╤П ╨┐╨╕╤В╨░╨╜╨╕╤П, ╨╜╨╛ ╤А╨░╨▒╨╛╤В╨░╨╡╤В ╨╜╨░╨╝╨╜╨╛╨│╨╛ ╨▒╤Л╤Б╤В╤А╨╡╨╡ ╨╢╨╡╤Б╤В╨║╨╕╤Е ╨┤╨╕╤Б╨║╨╛╨▓. ╨Ы╤О╨▒╨░╤П ╨┐╤А╨╛╨│╤А╨░╨╝╨╝╨░ ╤Б╨╜╨░╤З╨░╨╗╨░ ╨╖╨░╨│╤А╤Г╨╢╨░╨╡╤В╤Б╤П ╤Б ╨╢╨╡╤Б╤В╨║╨╛╨│╨╛ ╨┤╨╕╤Б╨║╨░ ╨▓ ╨╛╨┐╨╡╤А╨░╤В╨╕╨▓╨╜╤Г╤О ╨┐╨░╨╝╤П╤В╤М ╨╕ ╨╗╨╕╤И╤М ╨╖╨░╤В╨╡╨╝ ╨╜╨░╤З╨╕╨╜╨░╨╡╤В ╤А╨░╨▒╨╛╤В╤Г.</p><h4>╨Ю╤Б╨╜╨╛╨▓╨╜╤Л╨╡ ╨┐╨╛╨╜╤П╤В╨╕╤П</h4><p>╨Ю╨┐╨╡╤А╨░╤В╨╕╨▓╨╜╨░╤П ╨┐╨░╨╝╤П╤В╤М ╨╝╨╛╨╢╨╡╤В ╨╛╨▒╨╛╨╖╨╜╨░╤З╨░╤В╤М╤Б╤П ╨║╨░╨║ <strong>╨Ю╨Ч╨г</strong> (╨╛╨┐╨╡╤А╨░╤В╨╕╨▓╨╜╨╛╨╡ ╨╖╨░╨┐╨╛╨╝╨╕╨╜╨░╤О╤Й╨╡╨╡ ╤Г╤Б╤В╤А╨╛╨╣╤Б╤В╨▓╨╛) ╨╕╨╗╨╕ <strong>RAM</strong> (Random Access Memory тАФ ╨┐╨░╨╝╤П╤В╤М ╤Б ╨┐╤А╨╛╨╕╨╖╨▓╨╛╨╗╤М╨╜╤Л╨╝ ╨┤╨╛╤Б╤В╤Г╨┐╨╛╨╝). ╨Т╤Л╨┐╨╛╨╗╨╜╤П╨╡╤В╤Б╤П ╨▓ ╨▓╨╕╨┤╨╡ ╨╛╤В╨┤╨╡╨╗╤М╨╜╤Л╤Е ╨╝╨╛╨┤╤Г╨╗╨╡╨╣, ╤Б╨╛╤Б╤В╨╛╤П╤Й╨╕╤Е ╨╕╨╖ ╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╕╤Е ╤З╨╕╨┐╨╛╨▓ ╨┐╨░╨╝╤П╤В╨╕, ╨║╨╛╤В╨╛╤А╤Л╨╡ ╤Г╤Б╤В╨░╨╜╨░╨▓╨╗╨╕╨▓╨░╤О╤В╤Б╤П ╨▓ ╤Б╨╛╨╛╤В╨▓╨╡╤В╤Б╤В╨▓╤Г╤О╤Й╨╕╨╡ ╤А╨░╨╖╤К╨╡╨╝╤Л ╨╜╨░ ╤Б╨╕╤Б╤В╨╡╨╝╨╜╨╛╨╣ ╨┐╨╗╨░╤В╨╡.</p><h4>╨Ю╤А╨│╨░╨╜╨╕╨╖╨░╤Ж╨╕╤П ╤З╨╕╨┐╨╛╨▓ ╨┐╨░╨╝╤П╤В╨╕</h4><p>╨Ъ╨░╨╢╨┤╤Л╨╣ ╤З╨╕╨┐ ╨┐╨░╨╝╤П╤В╨╕ тАФ ╤Н╤В╨╛ ╨╝╨░╤В╤А╨╕╤Ж╨░ ╨╕╨╖ ╨╝╨╕╨╗╨╗╨╕╨╛╨╜╨╛╨▓ ╨╝╨╕╨╜╨╕╨░╤В╤О╤А╨╜╤Л╤Е ╨║╨╛╨╜╨┤╨╡╨╜╤Б╨░╤В╨╛╤А╨╛╨▓, ╤П╨▓╨╗╤П╤О╤Й╨╕╤Е╤Б╤П ╤Н╨╗╨╡╨╝╨╡╨╜╤В╨░╤А╨╜╤Л╨╝╨╕ ╤П╤З╨╡╨╣╨║╨░╨╝╨╕ ╨┐╨░╨╝╤П╤В╨╕. ╨Ъ╨╛╨╜╨┤╨╡╨╜╤Б╨░╤В╨╛╤А╤Л ╨╝╨╛╨│╤Г╤В ╨╜╨░╤Е╨╛╨┤╨╕╤В╤М╤Б╤П ╨▓ ╨╖╨░╤А╤П╨╢╨╡╨╜╨╜╨╛╨╝ (1) ╨╕╨╗╨╕ ╤А╨░╨╖╤А╤П╨╢╨╡╨╜╨╜╨╛╨╝ (0) ╤Б╨╛╤Б╤В╨╛╤П╨╜╨╕╨╕. ╨Ъ╤А╨╛╨╝╨╡ ╨║╨╛╨╜╨┤╨╡╨╜╤Б╨░╤В╨╛╤А╨╛╨▓, ╤З╨╕╨┐ ╤Б╨╛╨┤╨╡╤А╨╢╨╕╤В ╤Б╤Е╨╡╨╝╤Л ╤Г╨┐╤А╨░╨▓╨╗╨╡╨╜╨╕╤П ╤З╤В╨╡╨╜╨╕╨╡╨╝, ╨╖╨░╨┐╨╕╤Б╤М╤О ╨╕ <strong>╤А╨╡╨│╨╡╨╜╨╡╤А╨░╤Ж╨╕╨╡╨╣ ╨┤╨░╨╜╨╜╤Л╤Е</strong> тАФ ╨┤╨╗╤П ╨▓╨╛╤Б╤Б╤В╨░╨╜╨╛╨▓╨╗╨╡╨╜╨╕╤П ╨╖╨░╤А╤П╨┤╨░ ╨║╨╛╨╜╨┤╨╡╨╜╤Б╨░╤В╨╛╤А╨╛╨▓, ╨┐╨╛╤Б╨║╨╛╨╗╤М╨║╤Г ╤Б╨╛ ╨▓╤А╨╡╨╝╨╡╨╜╨╡╨╝ ╨╛╨╜╨╕ ╤Б╨░╨╝╨╛╨┐╤А╨╛╨╕╨╖╨▓╨╛╨╗╤М╨╜╨╛ ╤А╨░╨╖╤А╤П╨╢╨░╤О╤В╤Б╤П.</p><h4>╨С╨╗╨╛╤З╨╜╨░╤П ╨╛╤А╨│╨░╨╜╨╕╨╖╨░╤Ж╨╕╤П ╨┐╨░╨╝╤П╤В╨╕</h4><p>╨Х╨╝╨║╨╛╤Б╤В╤М ╨╛╤Б╨╜╨╛╨▓╨╜╨╛╨╣ ╨┐╨░╨╝╤П╤В╨╕ ╤Б╨╗╨╕╤И╨║╨╛╨╝ ╨▓╨╡╨╗╨╕╨║╨░ ╨┤╨╗╤П ╤А╨╡╨░╨╗╨╕╨╖╨░╤Ж╨╕╨╕ ╨╜╨░ ╨╛╨┤╨╜╨╛╨╣ ╨Ш╨Ь╨б. ╨Э╨╡╨╛╨▒╤Е╨╛╨┤╨╕╨╝╨╛╤Б╤В╤М ╨╛╨▒╤К╨╡╨┤╨╕╨╜╨╡╨╜╨╕╤П ╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╕╤Е ╨Ш╨Ь╨б ╨Ч╨г ╨▓╨╛╨╖╨╜╨╕╨║╨░╨╡╤В, ╨║╨╛╨│╨┤╨░ ╤А╨░╨╖╤А╤П╨┤╨╜╨╛╤Б╤В╤М ╤П╤З╨╡╨╡╨║ ╨╝╨╡╨╜╤М╤И╨╡ ╤А╨░╨╖╤А╤П╨┤╨╜╨╛╤Б╤В╨╕ ╤Б╨╗╨╛╨▓ ╨Т╨Ь. ╨г╨▓╨╡╨╗╨╕╤З╨╡╨╜╨╕╨╡ ╤А╨░╨╖╤А╤П╨┤╨╜╨╛╤Б╤В╨╕ ╤А╨╡╨░╨╗╨╕╨╖╤Г╨╡╤В╤Б╤П ╨╖╨░ ╤Б╤З╨╡╤В ╨╛╨▒╤К╨╡╨┤╨╕╨╜╨╡╨╜╨╕╤П ╨░╨┤╤А╨╡╤Б╨╜╤Л╤Е ╨▓╤Е╨╛╨┤╨╛╨▓ ╨Ш╨Ь╨б ╨Ч╨г. ╨Я╨╛╨╗╤Г╤З╨╡╨╜╨╜╤Г╤О ╤Б╨╛╨▓╨╛╨║╤Г╨┐╨╜╨╛╤Б╤В╤М ╨╝╨╕╨║╤А╨╛╤Б╤Е╨╡╨╝ ╨╜╨░╨╖╤Л╨▓╨░╤О╤В <strong>╨╝╨╛╨┤╤Г╨╗╨╡╨╝ ╨┐╨░╨╝╤П╤В╨╕</strong>. ╨Ю╨┤╨╕╨╜ ╨╕╨╗╨╕ ╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╛ ╨╝╨╛╨┤╤Г╨╗╨╡╨╣ ╨╛╨▒╤А╨░╨╖╤Г╤О╤В <strong>╨▒╨░╨╜╨║ ╨┐╨░╨╝╤П╤В╨╕</strong>.</p><h4>╨а╨░╤Б╤Б╨╗╨╛╨╡╨╜╨╕╨╡ ╨┐╨░╨╝╤П╤В╨╕</h4><p>╨С╨╗╨╛╤З╨╜╨╛╨╡ ╨┐╨╛╤Б╤В╤А╨╛╨╡╨╜╨╕╨╡ ╨┐╨░╨╝╤П╤В╨╕ ╨┐╨╛╨╖╨▓╨╛╨╗╤П╨╡╤В ╤Б╨╛╨║╤А╨░╤В╨╕╤В╤М ╨▓╤А╨╡╨╝╤П ╨┤╨╛╤Б╤В╤Г╨┐╨░ ╨▒╨╗╨░╨│╨╛╨┤╨░╤А╤П ╨┐╨╛╤В╨╡╨╜╤Ж╨╕╨░╨╗╤М╨╜╨╛╨╝╤Г ╨┐╨░╤А╨░╨╗╨╗╨╡╨╗╨╕╨╖╨╝╤Г. ╨С╨╛╨╗╤М╤И╨╡╨╣ ╤Б╨║╨╛╤А╨╛╤Б╤В╨╕ ╨┤╨╛╤Б╤В╤Г╨┐╨░ ╨╝╨╛╨╢╨╜╨╛ ╨┤╨╛╤Б╤В╨╕╤З╤М ╨╖╨░ ╤Б╤З╨╡╤В ╨╛╨┤╨╜╨╛╨▓╤А╨╡╨╝╨╡╨╜╨╜╨╛╨│╨╛ ╨┤╨╛╤Б╤В╤Г╨┐╨░ ╨║╨╛ ╨╝╨╜╨╛╨│╨╕╨╝ ╨▒╨░╨╜╨║╨░╨╝ ╨┐╨░╨╝╤П╤В╨╕. ╨Ь╨╡╤В╨╛╨┤╨╕╨║╨░ ╨╜╨░╨╖╤Л╨▓╨░╨╡╤В╤Б╤П <strong>╤А╨░╤Б╤Б╨╗╨╛╨╡╨╜╨╕╨╡╨╝ ╨┐╨░╨╝╤П╤В╨╕</strong>. ╨Т ╨╡╤С ╨╛╤Б╨╜╨╛╨▓╨╡ тАФ <strong>╤З╨╡╤А╨╡╨┤╨╛╨▓╨░╨╜╨╕╨╡ ╨░╨┤╤А╨╡╤Б╨╛╨▓</strong> (address interleaving), ╨╖╨░╨║╨╗╤О╤З╨░╤О╤Й╨╡╨╡╤Б╤П ╨▓ ╨╕╨╖╨╝╨╡╨╜╨╡╨╜╨╕╨╕ ╤Б╨╕╤Б╤В╨╡╨╝╤Л ╤А╨░╤Б╨┐╤А╨╡╨┤╨╡╨╗╨╡╨╜╨╕╤П ╨░╨┤╤А╨╡╤Б╨╛╨▓ ╨╝╨╡╨╢╨┤╤Г ╨▒╨░╨╜╨║╨░╨╝╨╕ ╨┐╨░╨╝╤П╤В╨╕.</p><h4>╨Ю╤А╨│╨░╨╜╨╕╨╖╨░╤Ж╨╕╤П ╨╝╨╕╨║╤А╨╛╤Б╤Е╨╡╨╝ ╨┐╨░╨╝╤П╤В╨╕</h4><p>╨Ш╨Ь╨б ╨┐╨░╨╝╤П╤В╨╕ ╨╛╤А╨│╨░╨╜╨╕╨╖╨╛╨▓╨░╨╜╤Л ╨▓ ╨▓╨╕╨┤╨╡ ╨╝╨░╤В╤А╨╕╤Ж╤Л ╤П╤З╨╡╨╡╨║. ╨Ъ╨░╨╢╨┤╤Л╨╣ ╨╖╨░╨┐╨╛╨╝╨╕╨╜╨░╤О╤Й╨╕╨╣ ╤Н╨╗╨╡╨╝╨╡╨╜╤В (╨Ч╨н) ╤Б╨┐╨╛╤Б╨╛╨▒╨╡╨╜ ╤Е╤А╨░╨╜╨╕╤В╤М ╨╛╨┤╨╕╨╜